const rejectingWithReason = (reason: unknown): AIProvider => ({
  // eslint-disable-next-line require-yield
  async *sendMessage(): AsyncGenerator<MessageChunk> {
    throw reason;
  },
  async generateStructured<T>(): Promise<T> {
    return {} as T;
  },
});

describe('ChatOrchestrator onError on non-Error rejections (unit)', () => {
  it('calls onError with an Error when a string is thrown', async () => {
    let receivedError: Error | undefined;
    const hooks: OrchestratorHooks = {
      onError: async (_session, error) => {
        receivedError = error;
      },
    };

    const orchestrator = createChatOrchestrator(
      rejectingWithReason('string boom'),
      promptBuilder,
      undefined,
      {hooks}
    );

    const rejection = await orchestrator.processMessage(sessionWith('hello')).catch(e => e);

    expect({
      rejection,
      receivedErrorType: receivedError?.constructor.name,
      message: receivedError?.message,
      // @ts-expect-error - cause is part of Error in modern node
      cause: receivedError?.cause,
    }).toEqual({
      rejection: 'string boom',
      receivedErrorType: 'Error',
      message: 'string boom',
      cause: 'string boom',
    });
  });
});

